class Solution{
    public String longestPalindrome(String s){
        int res_len = 0;
        int res_start = 0;
       for(int i = 0;i<s.length();i++){
           int L = i;
           int R = i;
           while(L>=0 && R<s.length() && s.charAt(L)==s.charAt(R)){
               if(R-L+1>res_len){
                   res_start = L;
                   res_len = R-L+1;
               }
               L--;
               R++;
           }
           L = i;
           R = i+1;
           while(L>=0 && R<s.length() && s.charAt(L)==s.charAt(R)){
               if(R-L+1>res_len){
                   res_start = L;
                   res_len = R-L+1;
               }
               L--;
               R++;
           }
       }
        return s.substring(res_start,res_start+res_len);
    }
}
